import { useState } from "react";
import axios from "axios";

const ZipUpload = () => {
  const [sliderZip, setSliderZip] = useState<File | null>(null);
  const [allZip, setAllZip] = useState<File | null>(null);
  const [bigZip, setBigZip] = useState<File | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: string) => {
    if (e.target.files) {
      if (type === "slider") setSliderZip(e.target.files[0]);
      if (type === "all") setAllZip(e.target.files[0]);
      if (type === "big") setBigZip(e.target.files[0]);
    }
  };

  const handleUpload = async () => {
    if (!sliderZip && !allZip && !bigZip) return alert("Please select at least one ZIP file");

    const formData = new FormData();
    if (sliderZip) formData.append("sliderZip", sliderZip);
    if (allZip) formData.append("allZip", allZip);
    if (bigZip) formData.append("bigZip", bigZip);

    try {
      const response = await axios.post("http://localhost:5000/upload-zip", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      console.log("Uploaded Data:", response.data);
    } catch (error) {
      console.error("Error uploading ZIP files:", error);
    }
  };

  return (
    <div>
      <h2>Upload ZIP Files</h2>
      <label>
        Slider Images:
        <input type="file" accept=".zip" onChange={(e) => handleFileChange(e, "slider")} />
      </label>
      <label>
        All Photos:
        <input type="file" accept=".zip" onChange={(e) => handleFileChange(e, "all")} />
      </label>
      <label>
        Big Photos:
        <input type="file" accept=".zip" onChange={(e) => handleFileChange(e, "big")} />
      </label>
      <button onClick={handleUpload}>Upload</button>
    </div>
  );
};

export default ZipUpload;
